    internal static SentenceBreakType GetSentenceBreakType(int scalar)
    {
        if ((uint)scalar > 0x10FFFF)
        {
            throw new System.ArgumentOutOfRangeException(nameof(scalar));
        }

        int low = 0;
        int high = BoundaryStarts.Length - 1;
        while (low <= high)
        {
            int middle = low + ((high - low) / 2);
            if (BoundaryStarts[middle] <= scalar)
            {
                low = middle + 1;
            }
            else
            {
                high = middle - 1;
            }
        }

        return BoundaryTypes[high];
    }
}
